css:
.pmpsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2a44;
    background: linear-gradient(180deg, #f4f7fc 0%, #eef2fa 100%);
    border-radius: 18px;
}

.pmpsim-container * {
    box-sizing: border-box;
}

.pmpsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1b2a6b 0%, #2f4bc7 60%, #3f7be0 100%);
    color: #ffffff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 14px 36px rgba(31, 51, 140, 0.28);
}

.pmpsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.pmpsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #cfe0ff;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.30);
    padding: 5px 14px;
    border-radius: 999px;
}

.pmpsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e4ecfb;
}

.pmpsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a5878;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.pmpsim-period-counter #currentDay,
.pmpsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f4bc7;
}

.pmpsim-round-name {
    background: rgba(47, 75, 199, 0.12);
    color: #2f4bc7;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.pmpsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b8541a;
    background: rgba(232, 122, 44, 0.14);
    border: 1px solid rgba(232, 122, 44, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.pmpsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.pmpsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e1e7f3;
    box-shadow: 0 6px 18px rgba(31, 51, 140, 0.08);
    border-top: 4px solid #9aa7c7;
}

.pmpsim-card-align { border-top-color: #2f4bc7; }
.pmpsim-card-conv { border-top-color: #1aa3a3; }
.pmpsim-card-growth { border-top-color: #6a3fd0; }
.pmpsim-card-revenue { border-top-color: #1f9d57; }

.pmpsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7794;
}

.pmpsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f2a44;
    font-variant-numeric: tabular-nums;
}

.pmpsim-card-align .pmpsim-value { color: #2f4bc7; }
.pmpsim-card-conv .pmpsim-value { color: #128585; }
.pmpsim-card-growth .pmpsim-value { color: #6a3fd0; }
.pmpsim-card-revenue .pmpsim-value { color: #1f9d57; }

.pmpsim-sublabel {
    font-size: 0.76rem;
    color: #7b87a3;
    line-height: 1.35;
}

.pmpsim-revenue-negative .pmpsim-value { color: #d6452e; }
.pmpsim-revenue-positive .pmpsim-value { color: #1f9d57; }

.pmpsim-growth-low { border-top-color: #d6452e; }
.pmpsim-growth-low .pmpsim-value { color: #d6452e; }
.pmpsim-growth-high { border-top-color: #1f9d57; }
.pmpsim-growth-high .pmpsim-value { color: #1f9d57; }

.pmpsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e1e7f3;
    color: #2c3756;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    box-shadow: 0 4px 12px rgba(31, 51, 140, 0.06);
}

.pmpsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #2f4bc7;
}

.pmpsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f4bc7;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 51, 140, 0.08);
}

.pmpsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.pmpsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1b2a6b;
    margin-bottom: 6px;
}

.pmpsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a466b;
}

.pmpsim-briefing-text strong { color: #2f4bc7; }
.pmpsim-briefing-text em { color: #b8541a; font-style: italic; }

.pmpsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e1e7f3;
    box-shadow: 0 6px 18px rgba(31, 51, 140, 0.08);
}

.pmpsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1b2a6b;
    border-bottom: 2px solid #eef2fa;
    padding-bottom: 8px;
}

.pmpsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3756;
    margin: 14px 0 6px;
}

.pmpsim-container select,
.pmpsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c7d2ea;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1f2a44;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.pmpsim-container select:focus,
.pmpsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f4bc7;
    box-shadow: 0 0 0 3px rgba(47, 75, 199, 0.16);
}

.pmpsim-container select option {
    background-color: #ffffff;
    color: #1f2a44;
}

.pmpsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f4bc7;
}

.pmpsim-range-readout,
.pmpsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4a5878;
    margin-top: 4px;
}

.pmpsim-range-readout span:nth-child(2),
.pmpsim-alloc-readout span:nth-child(2) {
    color: #2f4bc7;
    font-weight: 800;
}

.pmpsim-hint {
    font-size: 0.8rem;
    color: #7b87a3;
    margin-top: 4px;
    line-height: 1.4;
}

.pmpsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.pmpsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f9fd;
    border: 1px solid #e1e7f3;
    border-radius: 9px;
    padding: 8px 12px;
}

.pmpsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c3756;
}

.pmpsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.pmpsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.pmpsim-container .btn-primary {
    background: linear-gradient(135deg, #2f4bc7 0%, #3f7be0 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(47, 75, 199, 0.32);
}

.pmpsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.pmpsim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c7d2ea;
    color: #4a5878;
    background: transparent;
}

.pmpsim-coach {
    background: linear-gradient(160deg, #1b2a6b 0%, #243a8f 100%);
    color: #e7eefb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(27, 42, 107, 0.30);
}

.pmpsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9db8ff;
    margin-bottom: 8px;
}

.pmpsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.pmpsim-coach-body strong { color: #9db8ff; }
.pmpsim-coach-body em { color: #ffc98a; font-style: italic; }

.pmpsim-history,
.pmpsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e1e7f3;
    box-shadow: 0 6px 18px rgba(31, 51, 140, 0.08);
}

.pmpsim-history h3,
.pmpsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1b2a6b;
}

.pmpsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c3756;
}

.pmpsim-container table#usfHistoryTable th {
    background: #eef2fa;
    color: #2f4bc7;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #dde5f3;
}

.pmpsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2fa;
    color: #3a466b;
}

.pmpsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fd;
}

.pmpsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .pmpsim-container {
        padding: 14px;
    }
    .pmpsim-header h1 {
        font-size: 1.7rem;
    }
    .pmpsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .pmpsim-value {
        font-size: 2rem;
    }
    .pmpsim-clock {
        margin-left: 0;
    }
    .pmpsim-period-counter {
        font-size: 0.88rem;
    }
    .pmpsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .pmpsim-alloc-row {
        flex-wrap: wrap;
    }
    .pmpsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .pmpsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.pmpsim-cm { background:#f4f5fb; color:#171a2b; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.pmpsim-cm-head { text-align:center; border-bottom:1px solid #dde0ef; padding-bottom:14px; margin-bottom:16px; }
.pmpsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#565d78; font-weight:700; }
.pmpsim-cm-scorewrap { margin:8px 0 2px; }
.pmpsim-cm-score { font-size:52px; font-weight:800; color:#4a54c4; line-height:1; }
.pmpsim-cm-score-max { font-size:20px; color:#8b90ac; font-weight:600; }
.pmpsim-cm-grade { font-size:19px; font-weight:700; color:#171a2b; margin-top:4px; }
.pmpsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.pmpsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.pmpsim-cm-met { background:#d3e8de; color:#1b6a4f; }
.pmpsim-cm-fail { background:#f1dcdb; color:#a13830; }
.pmpsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.pmpsim-cm-metric { background:#e7e9f5; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.pmpsim-cm-metric-val { font-size:22px; font-weight:800; color:#171a2b; }
.pmpsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#565d78; margin-top:3px; }
.pmpsim-cm-insights { background:#e7e9f5; border-radius:10px; padding:14px 18px; }
.pmpsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#565d78; font-weight:700; margin-bottom:8px; }
.pmpsim-cm-insights ul { margin:0; padding-left:18px; }
.pmpsim-cm-insights li { font-size:14px; line-height:1.5; color:#2c2f40; margin-bottom:7px; }

