(function() {
    'use strict';

    class PlanMeetsPipelineAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Plan Meets Pipeline`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card — Northbridge Systems Inc.
            this.ARR = 64;                 // CAD 64M annual recurring revenue
            this.BUDGET = 9.6;             // CAD 9.6M frozen flat commercial budget
            this.BASE_GROWTH = 8;          // 8% current growth (down from 22%)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    align: 25,             // alignment index — do mkt & sales act as one system (0–100)
                    conv: 20,              // conversion health vs the funnel leak (0–100)
                    growth: this.BASE_GROWTH, // projected ARR growth %
                    revenue: 0,            // CAD M annual ARR lift vs status quo
                    budgetUsed: this.BUDGET, // budget is frozen — fully committed once reallocated
                    deprioritized: false,  // did the team deliberately drop a segment?
                    salesOwns: false,      // did sales OWN the plan (not just nod)?
                    volumeChase: false,    // chased more leads instead of fixing conversion
                    siloedScorecard: false,// left mkt & sales on separate KPIs
                    alignHistory: [25],
                    convHistory: [20],
                    growthHistory: [this.BASE_GROWTH],
                    revenueHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately WRONG-LEANING mix —
                // a blind click-through must not auto-win (Common Errors baked in).
                state.decisions = {
                    leak: `volume`,
                    root: `information`,
                    rigor: 40,
                    focus: `all4`,
                    position: `product`,
                    demand: `3000`,
                    stop: 30,
                    sla: `none`,
                    comp: `logos`,
                    motion: `discount`,
                    buyin: 40,
                    demandgen: 2.4,
                    sdr: 2.4,
                    tradeshows: 2.4,
                    brand: 2.4,
                    follow: `fashion`,
                    scorecard: `separate`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const lk = document.getElementById(`leakInput`);
                const rt = document.getElementById(`rootInput`);
                const rg = document.getElementById(`rigorInput`);
                if (lk) decisions.leak = lk.value;
                if (rt) decisions.root = rt.value;
                if (rg) decisions.rigor = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const fc = document.getElementById(`focusInput`);
                const ps = document.getElementById(`positionInput`);
                const dm = document.getElementById(`demandInput`);
                const st = document.getElementById(`stopInput`);
                if (fc) decisions.focus = fc.value;
                if (ps) decisions.position = ps.value;
                if (dm) decisions.demand = dm.value;
                if (st) decisions.stop = parseInt(st.value, 10);
                if (!Number.isFinite(decisions.stop) || decisions.stop < 0 || decisions.stop > 100) {
                    warn(`warn_stop_range`); return false;
                }
            } else if (round === 3) {
                const sl = document.getElementById(`slaInput`);
                const cp = document.getElementById(`compInput`);
                const mt = document.getElementById(`motionInput`);
                const bi = document.getElementById(`buyinInput`);
                if (sl) decisions.sla = sl.value;
                if (cp) decisions.comp = cp.value;
                if (mt) decisions.motion = mt.value;
                if (bi) decisions.buyin = parseInt(bi.value, 10);
                if (!Number.isFinite(decisions.buyin) || decisions.buyin < 0 || decisions.buyin > 100) {
                    warn(`warn_buyin_range`); return false;
                }
            } else if (round === 4) {
                const dg = document.getElementById(`demandgenInput`);
                const sd = document.getElementById(`sdrInput`);
                const ts = document.getElementById(`tradeshowsInput`);
                const br = document.getElementById(`brandInput`);
                const fl = document.getElementById(`followInput`);
                const sc = document.getElementById(`scorecardInput`);
                if (dg) decisions.demandgen = parseFloat(dg.value);
                if (sd) decisions.sdr = parseFloat(sd.value);
                if (ts) decisions.tradeshows = parseFloat(ts.value);
                if (br) decisions.brand = parseFloat(br.value);
                if (fl) decisions.follow = fl.value;
                if (sc) decisions.scorecard = sc.value;
                const parts = [decisions.demandgen, decisions.sdr, decisions.tradeshows, decisions.brand];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.demandgen + decisions.sdr + decisions.tradeshows + decisions.brand) * 10) / 10;
                if (Math.abs(total - this.BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let alignDelta = 0, convDelta = 0, growthDelta = 0, revenueDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE — find the real leak and the real root cause.
                // Common Error 2 surfaces here as "the leak is volume".
                switch (d.leak) {
                    case `handoff`: convDelta += 12; alignDelta += 8; coachKey = `coach_r1_handoff`; break;
                    case `volume`: convDelta -= 4; coachKey = `coach_r1_volume`; ds.volumeChase = true; break;
                    case `close`: convDelta += 2; coachKey = `coach_r1_close`; break;
                    case `product`: convDelta -= 2; alignDelta -= 2; coachKey = `coach_r1_product`; break;
                }

                switch (d.root) {
                    case `definitions`: alignDelta += 12; convDelta += 4; coachKey = (d.leak === `handoff`) ? `coach_r1_sharp` : coachKey; break;
                    case `information`: alignDelta += 2; break;
                    case `effort`: alignDelta -= 6; coachKey = `coach_r1_effort`; break;
                    case `luck`: alignDelta -= 8; convDelta -= 2; coachKey = `coach_r1_luck`; break;
                }

                // Diagnostic rigor — quantifying the cost of the 78% untouched leads.
                if (d.rigor >= 60) { alignDelta += 6; convDelta += 4; }
                else if (d.rigor <= 25) { alignDelta -= 4; convDelta -= 3; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.leak === `handoff` && d.root === `definitions`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // BUILD THE MARKET PLAN (Marketing Led).
                // Common Error 3: refusing to deprioritize. Common Error 2: volume over conversion.
                switch (d.focus) {
                    case `three`: convDelta += 10; growthDelta += 1.2; ds.deprioritized = true; coachKey = `coach_r2_three`; break;
                    case `two`: convDelta += 8; growthDelta += 1.0; ds.deprioritized = true; coachKey = `coach_r2_two`; break;
                    case `one`: convDelta += 2; growthDelta -= 0.5; coachKey = `coach_r2_one`; break;
                    case `all4`: convDelta -= 6; growthDelta -= 1.0; alignDelta -= 2; coachKey = `coach_r2_all4`; break;
                }

                switch (d.position) {
                    case `customer`: alignDelta += 8; convDelta += 6; growthDelta += 0.8; break;
                    case `product`: convDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_product` : coachKey; break;
                    case `price`: growthDelta -= 0.6; convDelta -= 2; coachKey = `coach_r2_price`; break;
                }

                // Demand target — more leads vs fixing conversion (Common Error 2).
                switch (d.demand) {
                    case `1400`: convDelta += 8; coachKey = (coachKey === `coach_default`) ? `coach_r2_fewer` : coachKey; break;
                    case `2000`: convDelta += 4; break;
                    case `3000`: convDelta -= 8; ds.volumeChase = true; coachKey = `coach_r2_morevolume`; break;
                }

                // What marketing stops doing to fund the focus on a frozen budget.
                if (d.stop >= 50) { convDelta += 4; growthDelta += 0.4; }
                else if (d.stop <= 10) { convDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r2_nostop` : coachKey; }
                else if (d.stop >= 80) { convDelta -= 2; growthDelta -= 0.3; coachKey = `coach_r2_overcut`; }

                summaryKey = (ds.deprioritized && d.position === `customer` && d.demand !== `3000`) ? `sum_r2_good` :
                             (d.demand === `3000` ? `sum_r2_volume` : `sum_r2_weak`);
            } else if (round === 3) {
                // ALIGN SALES EXECUTION (Sales Driven).
                // Common Error 1: plan without buy-in.
                switch (d.sla) {
                    case `sla`: alignDelta += 12; convDelta += 10; coachKey = `coach_r3_sla`; break;
                    case `oneway`: alignDelta += 2; convDelta += 2; coachKey = `coach_r3_oneway`; break;
                    case `none`: alignDelta -= 6; convDelta -= 4; coachKey = `coach_r3_nosla`; break;
                }

                switch (d.comp) {
                    case `fit`: alignDelta += 10; convDelta += 6; growthDelta += 1.0; break;
                    case `quota`: alignDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_quota` : coachKey; break;
                    case `logos`: alignDelta -= 8; growthDelta -= 0.8; coachKey = `coach_r3_logos`; break;
                }

                switch (d.motion) {
                    case `value`: convDelta += 6; growthDelta += 1.2; break;
                    case `feature`: convDelta -= 1; break;
                    case `discount`: growthDelta -= 0.8; convDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_discount` : coachKey; break;
                }

                // Sales VP ownership — the negotiated buy-in (Facilitator Decision Tree #1).
                if (d.buyin >= 60) {
                    ds.salesOwns = true; alignDelta += 8; convDelta += 4;
                    if (d.comp === `fit` && d.sla === `sla`) coachKey = `coach_r3_owned`;
                } else if (d.buyin <= 25) {
                    alignDelta -= 8; coachKey = `coach_r3_nobuyin`;
                }

                summaryKey = (d.sla === `sla` && d.comp === `fit` && ds.salesOwns) ? `sum_r3_good` :
                             (!ds.salesOwns && d.buyin <= 25 ? `sum_r3_nobuyin` : `sum_r3_weak`);
            } else if (round === 4) {
                // REALLOCATE & RECOVER on the frozen budget.
                // Common Error 4: channel fashion. Common Error 5: siloed scorecards.
                const dg = d.demandgen, sd = d.sdr, ts = d.tradeshows, br = d.brand;

                // Spend that serves revenue-coupled, segment-aligned channels rewards conversion;
                // generic brand spend is "largely uncoupled from revenue" per the concept.
                convDelta += (dg - 0.8) * 2.2 + (sd - 0.5) * 2.6 - (br - 1.1) * 1.4;
                growthDelta += (dg - 0.8) * 0.25 + (sd - 0.5) * 0.30;

                // Follow the segments, not channel fashion (Facilitator Decision Tree #4).
                switch (d.follow) {
                    case `segment`: convDelta += 8; growthDelta += 1.0; alignDelta += 4; break;
                    case `even`: coachKey = `coach_r4_even`; break;
                    case `fashion`: convDelta -= 6; growthDelta -= 0.6; coachKey = `coach_r4_fashion`; break;
                }

                // Joint vs siloed scorecard (Facilitator Decision Tree #5).
                switch (d.scorecard) {
                    case `shared`: alignDelta += 12; growthDelta += 0.8; coachKey = (coachKey === `coach_default`) ? `coach_r4_shared` : coachKey; break;
                    case `separate`: alignDelta -= 10; growthDelta -= 0.6; ds.siloedScorecard = true; coachKey = `coach_r4_siloed`; break;
                }

                // SDR starvation check — can't honor the SLA with no capacity to work the leads.
                if (sd <= 0.5) { convDelta -= 4; coachKey = `coach_r4_nosdr`; }

                summaryKey = (d.follow === `segment` && d.scorecard === `shared`) ? `sum_r4_good` :
                             (d.scorecard === `separate` ? `sum_r4_siloed` : `sum_r4_weak`);
            }

            // Apply alignment & conversion deltas, clamped 0–100.
            ds.align = Math.max(0, Math.min(100, Math.round(ds.align + alignDelta)));
            ds.conv = Math.max(0, Math.min(100, Math.round(ds.conv + convDelta)));

            // Growth is driven directly by the round deltas, but capped by how aligned/converting
            // the engine actually is — a high target with low alignment cannot be realized.
            const realization = (ds.align / 100) * 0.6 + (ds.conv / 100) * 0.4; // 0..1
            const cappedGrowthDelta = growthDelta * (0.4 + 0.6 * realization);
            ds.growth = Math.round((ds.growth + cappedGrowthDelta) * 10) / 10;
            ds.growth = Math.max(0, Math.min(30, ds.growth));

            // Revenue lift = incremental ARR growth above the 8% base, applied to the C$64M ARR.
            ds.revenue = Math.round((this.ARR * (ds.growth - this.BASE_GROWTH) / 100) * 10) / 10;

            ds.alignHistory.push(ds.align);
            ds.convHistory.push(ds.conv);
            ds.growthHistory.push(ds.growth);
            ds.revenueHistory.push(ds.revenue);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            return {
                period: state.currentPeriod,
                align: ds.align,
                alignDelta: Math.round(alignDelta),
                conv: ds.conv,
                convDelta: Math.round(convDelta),
                growth: ds.growth,
                growthDelta: Math.round(cappedGrowthDelta * 10) / 10,
                revenue: ds.revenue,
                deprioritized: ds.deprioritized,
                salesOwns: ds.salesOwns,
                volumeChase: ds.volumeChase,
                siloedScorecard: ds.siloedScorecard,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // CAD: English "C$2.4M"; Spanish "2,4 M C$" (comma decimal, symbol after).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M C$`;
            }
            return `${sign}C$${abs.toFixed(1)}M`;
        }

        _fmtPct(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return lang === `es` ? `${s.replace(`.`, `,`)}%` : `${s}%`;
        }

