                if (card) {
                    card.classList.toggle(`pmpsim-growth-high`, Number(v) >= 15);
                    card.classList.toggle(`pmpsim-growth-low`, Number(v) <= 8);
                }
                return self._fmtPct(Number(v));
            });
            uiManager.bind(`revenueDisplay`, `domainState.revenue`, (v) => {
                const card = document.querySelector(`.pmpsim-card-revenue`);
                if (card) {
                    card.classList.toggle(`pmpsim-revenue-positive`, Number(v) > 0.05);
                    card.classList.toggle(`pmpsim-revenue-negative`, Number(v) < -0.05);
                }
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.BUDGET);
