            if (rg && rgReadout) {
                rgReadout.textContent = rg.value;
                rg.addEventListener(`input`, function() { rgReadout.textContent = rg.value; });
            }

            // Stop slider readout.
            const st = document.getElementById(`stopInput`);
            const stReadout = document.getElementById(`stopReadout`);
            if (st && stReadout) {
                stReadout.textContent = st.value;
                st.addEventListener(`input`, function() { stReadout.textContent = st.value; });
            }

            // Buy-in slider readout.
            const bi = document.getElementById(`buyinInput`);
            const biReadout = document.getElementById(`buyinReadout`);
            if (bi && biReadout) {
                biReadout.textContent = bi.value;
                bi.addEventListener(`input`, function() { biReadout.textContent = bi.value; });
            }

            // Budget live total (must hit C$9.6M).
            const allocIds = [`demandgenInput`, `sdrInput`, `tradeshowsInput`, `brandInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.pmpsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET) > 0.001) ? `#d6452e` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

