        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.alignHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                pmpChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.alignHistory },
                        { data: ds.convHistory },
                        { data: ds.growthHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 composite formula, verbatim — single source of truth.
            const align = Math.round(ds.align);
            const conv = Math.round(ds.conv);
            const growth = ds.growth;
            const revenue = ds.revenue;
            const growthScore = Math.max(0, Math.min(100, ((growth - 8) / (22 - 8)) * 100));
            return Math.round(align * 0.34 + conv * 0.30 + growthScore * 0.24 + Math.max(0, Math.min(12, revenue)) / 12 * 100 * 0.12);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const align = Math.round(ds.align);
            const conv = Math.round(ds.conv);
            const growth = ds.growth;
            const revenue = ds.revenue;

            // Composite: alignment, conversion, growth headroom, plus a revenue-lift bonus.
            const composite = this._composite(ds);

            const aligned = align >= 60;
            const converting = conv >= 60;
            const growing = growth >= 14;
            const onePlan = ds.salesOwns && !ds.siloedScorecard && ds.deprioritized;

            let performanceKey = `grade_two`;
            if (aligned && converting && growing && onePlan && composite >= 75) performanceKey = `grade_engine`;
            else if (aligned && converting) performanceKey = `grade_meets`;
            else if (ds.volumeChase && conv < 45) performanceKey = `grade_bucket`;
            else if (!ds.salesOwns && align < 45) performanceKey = `grade_slide`;
            else if (composite >= 55) performanceKey = `grade_partial`;
            const met = aligned && converting && growing && onePlan && composite >= 75;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (aligned && converting && onePlan) insights.push(window.mySimulation.t(`insight_engine`));
            else if (ds.volumeChase && conv < 45) insights.push(window.mySimulation.t(`insight_volume`));
            else if (!ds.salesOwns) insights.push(window.mySimulation.t(`insight_noownership`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (!ds.deprioritized) insights.push(window.mySimulation.t(`insight_nodeprioritize`));
            if (ds.siloedScorecard) insights.push(window.mySimulation.t(`insight_siloed`));
            if (revenue >= 4) insights.push(window.mySimulation.t(`insight_revenue_strong`));
            else if (revenue <= 0) insights.push(window.mySimulation.t(`insight_revenue_flat`));
            if (aligned && conv >= 65) insights.push(window.mySimulation.t(`insight_handoff_closed`));

            return {
                align: align,
                conv: conv,
                growth: growth,
                revenue: revenue,
                aligned: aligned,
                converting: converting,
                growing: growing,
                onePlan: onePlan,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                volumeChase: !!ds.volumeChase,
                salesOwns: !!ds.salesOwns,
                siloedScorecard: !!ds.siloedScorecard,
                deprioritized: !!ds.deprioritized,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="pmpsim-cm-badge ` + (s.met ? `pmpsim-cm-met` : `pmpsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.volumeChase) badges.push(`<span class="pmpsim-cm-badge pmpsim-cm-fail">` + t(`cm_fail_volume`) + `</span>`);
            if (s.siloedScorecard) badges.push(`<span class="pmpsim-cm-badge pmpsim-cm-fail">` + t(`cm_fail_siloed`) + `</span>`);
            if (!s.salesOwns) badges.push(`<span class="pmpsim-cm-badge pmpsim-cm-fail">` + t(`cm_fail_ownership`) + `</span>`);
            if (!s.deprioritized) badges.push(`<span class="pmpsim-cm-badge pmpsim-cm-fail">` + t(`cm_fail_focus`) + `</span>`);
            const kpi = (label, val) => `<div class="pmpsim-cm-metric"><div class="pmpsim-cm-metric-val">` + val + `</div><div class="pmpsim-cm-metric-lbl">` + label + `</div></div>`;
            const gr = (s.growth != null) ? (this._fmtPct ? this._fmtPct(s.growth) : (s.growth + `%`)) : ``;
            const rv = (s.revenue != null) ? (this._fmtMoney ? this._fmtMoney(s.revenue) : (`` + s.revenue)) : ``;
            const kpis = kpi(t(`cm_align`), (s.align != null ? Math.round(s.align) : 0))
                + kpi(t(`cm_conv`), (s.conv != null ? Math.round(s.conv) : 0))
                + kpi(t(`cm_growth`), gr)
                + kpi(t(`cm_revenue`), rv);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="pmpsim-cm">`
                + `<div class="pmpsim-cm-head"><div class="pmpsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="pmpsim-cm-scorewrap"><span class="pmpsim-cm-score">` + score + `</span><span class="pmpsim-cm-score-max">/100</span></div>`
                + `<div class="pmpsim-cm-grade">` + grade + `</div>`
                + `<div class="pmpsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="pmpsim-cm-metrics">` + kpis + `</div>`
                + `<div class="pmpsim-cm-insights"><div class="pmpsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
