            if (!ds.salesOwns && state.currentPeriod >= 3) return window.mySimulation.t(`hint_ownership`);
            if (ds.siloedScorecard) return window.mySimulation.t(`hint_siloed`);
            if (ds.align >= 65 && ds.conv >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

